import {printers,choosePrinter} from './printers.js?v=37';
const key='popomo-design-printer';
export function resolvePrinter(list,id){if(list.length===1)return list[0];return list.find(p=>p.id===id)||list.find(p=>p.primary)||list[0]||null;}
export function getDesignPrinter(id){let preferred=id;try{preferred=preferred||sessionStorage.getItem(key);}catch{}return resolvePrinter(printers,preferred);}
export function setDesignPrinter(id){const printer=resolvePrinter(printers,id);if(printer){try{sessionStorage.setItem(key,printer.id);}catch{}}return printer;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountDesignPrinter(root,{printerId,onChange}={}){if(!root)return;let selected=getDesignPrinter(printerId);if(selected)setDesignPrinter(selected.id);function render(){const en=document.documentElement.lang.startsWith('en'),t=(zh,eng)=>en?eng:zh;if(!selected){root.innerHTML=`<p class="design-printer-empty">${t('暂无可用打印设备','No printer available')}</p>`;return;}root.innerHTML=`<div class="design-printer-summary"><span class="design-printer-symbol" aria-hidden="true">⌖</span><div><span class="design-printer-label">${t('打印设备','Print device')}${selected.primary?` · ${t('主要设备','Primary device')}`:''}</span><strong>${esc(selected.name.replace(/^POPOMO · /,''))}</strong></div>${printers.length>1?`<button class="tertiary" type="button" data-switch-design-printer>${t('切换设备','Change printer')}</button>`:`<span class="design-printer-auto">${t('已自动选择','Selected automatically')}</span>`}</div>`;root.querySelector('[data-switch-design-printer]')?.addEventListener('click',()=>choosePrinter({selectedId:selected.id,requestLocation:false,onSelect:p=>{selected=setDesignPrinter(p.id);onChange?.(selected);render();}}));}render();}
window.PopomoPrinterSelection={get:getDesignPrinter,set:setDesignPrinter};
